405	// members that read the same path and never with another member of the host.
406	func TestSharedWalkFailureOfOneMemberDoesNotReachAnother(t *testing.T) {
407		lister := func(_ context.Context, _, catalogPrefix, _, _ string, _, _ int) ([]string, bool, error) {
408			if catalogPrefix == "docker-group" {
409				return nil, false, &oci.StatusError{Code: 404, Source: oci.SourceRegistry}
410			}
411			return []string{"api"}, false, nil
412		}
413		ctx := WithSharedWalks(context.Background())
414		for _, tc := range []struct {
415			prefix string
416			want   Verdict
417		}{{"docker-group", VerdictRefused}, {"docker-hosted", VerdictOK}, {"docker-group", VerdictRefused}} {
418			imgs, partial, err := CatalogSearcher{List: lister}.Search(ctx, memberUnder("k-"+tc.prefix, tc.prefix, "u", "p"), Query{Text: "api"})
419			if got := Classify(err, len(imgs), partial).Verdict; got != tc.want {
420				t.Errorf("%s: verdict = %v, want %v (err = %v)", tc.prefix, got, tc.want, err)
421			}
422		}
423	}
