425	// The key shows where the walk goes, never who walks it.
426	func TestWalkKeyShowsThePathNeverTheIdentity(t *testing.T) {
427		const user, pass = "alice-user", "hunter2-secret"
428		s := &walkShare{}
429		if _, err := rand.Read(s.secret[:]); err != nil {
430			t.Fatal(err)
431		}
432		under := memberUnder("k", "docker-hosted", user, pass)
433		under.APIURL = "https://" + user + ":" + pass + "@reg.example/"
434		key := s.keyFor(under)
435	
436		if key.catalogPrefix != "docker-hosted" {
437			t.Errorf("catalogPrefix = %q, want docker-hosted", key.catalogPrefix)
438		}
439		for _, out := range []string{
440			key.String(), fmt.Sprintf("%v", key), fmt.Sprintf("%+v", key), fmt.Sprintf("%#v", key), fmt.Sprintf("%s", &key),
441		} {
442			if !strings.Contains(out, "docker-hosted") {
443				t.Errorf("%q does not show the catalog path", out)
444			}
445			for _, leak := range []string{user, pass} {
446				if strings.Contains(out, leak) {
447					t.Errorf("%q leaks %q", out, leak)
448				}
449			}
450		}
451		if got := (walkKey{apiURL: "https://reg.example", catalogPrefix: "docker-proxy"}).String(); !strings.Contains(got, "docker-proxy") {
452			t.Errorf("String() = %q does not show the catalog path", got)
453		}
454	}
