456	func TestWalkKeyCatalogPrefix(t *testing.T) {
457		s := &walkShare{}
458		hosted := s.keyFor(memberUnder("a", "docker-hosted", "u", "p"))
459		proxy := s.keyFor(memberUnder("b", "docker-proxy", "u", "p"))
460		if hosted == proxy {
461			t.Error("two catalog prefixes of one host and identity share a key")
462		}
463		if again := s.keyFor(memberUnder("c", "docker-hosted", "u", "p")); again != hosted {
464			t.Error("one catalog prefix gets two keys")
465		}
466		// A root target filtering on a prefix (R1) walks the root: its key carries none.
467		root := s.keyFor(member("d", "docker-hosted", "u", "p"))
468		if root.catalogPrefix != "" {
469			t.Errorf("a root walk's catalogPrefix = %q, want empty", root.catalogPrefix)
470		}
471		if root == hosted {
472			t.Error("a root walk and a walk under a prefix share a key")
473		}
474	}

